{"command": "cat > /prediction.json << 'JSONEOF'
{
    "/workspace/vllm-project/vllm/vllm/v1/sample/rejection_sampler.py": {
        "rejection_greedy_sample_kernel": "@triton.jit(do_not_specialize=[\"max_spec_len\"])\ndef rejection_greedy_sample_kernel(\n    output_token_ids_ptr,  # [batch_size, max_spec_len + 1]\n    cu_num_draft_tokens_ptr,  # [batch_size]\n    draft_token_ids_ptr,  # [num_tokens]\n    target_argmax_ptr,  # [num_tokens]\n    bonus_token_ids_ptr,  # [batch_size]\n    is_greedy_ptr,  # [batch_size] or None\n    max_spec_len,\n):\n    req_idx = tl.program_id(0)\n    \n    # Get the start and end indices for this request\n    if req_idx == 0:\n        start_idx = 0\n    else:\n        start_idx = tl.load(cu_num_draft_tokens_ptr + req_idx - 1)\n    end_idx = tl.load(cu_num_draft_tokens_ptr + req_idx)\n    num_draft_tokens = end_idx - start_idx\n    \n    # Check if this request is greedy\n    # If is_greedy_ptr is None, all requests are greedy\n    is_greedy = True\n    if is_greedy_ptr is not None:\n        is_greedy = tl.load(is_greedy_ptr + req_idx)\n    \n    # If not greedy, skip this request (it will be handled by random kernel)\n    if not is_greedy:\n        return\n    \n    # Handle empty sequence case\n    if num_draft_tokens == 0:\n        # Just add the bonus token\n        bonus_token_id = tl.load(bonus_token_ids_ptr + req_idx)\n        tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1), bonus_token_id)\n        return\n    \n    # Process each draft token position\n    all_accepted = True\n    for pos in range(max_spec_len):\n        if pos >= num_draft_tokens:\n            break\n        \n        token_idx = start_idx + pos\n        draft_token_id = tl.load(draft_token_ids_ptr + token_idx)\n        target_argmax = tl.load(target_argmax_ptr + token_idx)\n        \n        # For greedy sampling: accept if draft_token == target_argmax\n        if draft_token_id == target_argmax:\n            # Accept the draft token\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, draft_token_id)\n        else:\n            # Reject: use target_argmax as recovered token and stop\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, target_argmax)\n            all_accepted = False\n            break\n    \n    # If all draft tokens were accepted, add the bonus token\n    if all_accepted:\n        bonus_token_id = tl.load(bonus_token_ids_ptr + req_idx)\n        tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + num_draft_tokens, bonus_token_id)",
        "rejection_random_sample_kernel": "@triton.jit(do_not_specialize=[\"max_spec_len\"])\ndef rejection_random_sample_kernel(\n    output_token_ids_ptr,  # [batch_size, max_spec_len + 1]\n    cu_num_draft_tokens_ptr,  # [batch_size]\n    draft_token_ids_ptr,  # [num_tokens]\n    draft_probs_ptr,  # [num_tokens, vocab_size] or None\n    target_probs_ptr,  # [num_tokens, vocab_size]\n    bonus_token_ids_ptr,  # [batch_size]\n    recovered_token_ids_ptr,  # [num_tokens]\n    uniform_probs_ptr,  # [num_tokens]\n    is_greedy_ptr,  # [batch_size]\n    max_spec_len,\n    vocab_size,\n    IS_NGRAM: tl.constexpr,\n):\n    req_idx = tl.program_id(0)\n    \n    # Get the start and end indices for this request\n    if req_idx == 0:\n        start_idx = 0\n    else:\n        start_idx = tl.load(cu_num_draft_tokens_ptr + req_idx - 1)\n    end_idx = tl.load(cu_num_draft_tokens_ptr + req_idx)\n    num_draft_tokens = end_idx - start_idx\n    \n    # Check if this request is greedy - skip if so (already handled by greedy kernel)\n    is_greedy = False\n    if is_greedy_ptr is not None:\n        is_greedy = tl.load(is_greedy_ptr + req_idx)\n    \n    if is_greedy:\n        return\n    \n    # Handle empty sequence case\n    if num_draft_tokens == 0:\n        # Just add the bonus token\n        bonus_token_id = tl.load(bonus_token_ids_ptr + req_idx)\n        tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1), bonus_token_id)\n        return\n    \n    # Process each draft token position\n    all_accepted = True\n    for pos in range(max_spec_len):\n        if pos >= num_draft_tokens:\n            break\n        \n        token_idx = start_idx + pos\n        draft_token_id = tl.load(draft_token_ids_ptr + token_idx)\n        uniform_prob = tl.load(uniform_probs_ptr + token_idx)\n        recovered_token_id = tl.load(recovered_token_ids_ptr + token_idx)\n        \n        # Calculate acceptance probability\n        if IS_NGRAM:\n            # For n-gram, draft_probs is None\n            # Accept with probability min(1, target_prob[draft_token])\n            target_prob_draft = tl.load(target_probs_ptr + token_idx * vocab_size + draft_token_id)\n            accept_prob = target_prob_draft\n        else:\n            # Standard rejection sampling\n            # accept_prob = min(1, target_prob / draft_prob)\n            draft_prob = tl.load(draft_probs_ptr + token_idx * vocab_size + draft_token_id)\n            target_prob_draft = tl.load(target_probs_ptr + token_idx * vocab_size + draft_token_id)\n            accept_prob = tl.minimum(1.0, target_prob_draft / draft_prob)\n        \n        # Accept or reject based on uniform random number\n        if uniform_prob < accept_prob:\n            # Accept the draft token\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, draft_token_id)\n        else:\n            # Reject: use recovered token and stop\n            tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + pos, recovered_token_id)\n            all_accepted = False\n            break\n    \n    # If all draft tokens were accepted, add the bonus token\n    if all_accepted:\n        bonus_token_id = tl.load(bonus_token_ids_ptr + req_idx)\n        tl.store(output_token_ids_ptr + req_idx * (max_spec_len + 1) + num_draft_tokens, bonus_token_id)"
    }
}
JSONEOF
cat /prediction.json"}

